// Example Grafana panel target -- CloudWatch metrics query (simplified JSON)
{
  "datasource": "CloudWatch",
  "namespace": "Pipeline/Orders",
  "metricName": "RecordsProcessed",
  "dimensions": { "Source": "$source" },     // driven by template variable
  "statistic": "Sum",
  "period": "3600"
}

// Metric Math -- error rate as a percentage (query C combines A and B)
// Query A: Pipeline/Orders ValidationErrors, statistic Sum
// Query B: Pipeline/Orders RecordsProcessed, statistic Sum
// Query C (Metric Math expression):
100 * (A / B)

// CloudWatch Logs Insights embedded directly in a Grafana panel
fields @timestamp, source, duration_ms
| filter source = "$source"
| stats avg(duration_ms) as avg_duration by bin(1h)

// Template variable definition (Dashboard Settings -> Variables)
// Name: source
// Type: Query
// Data source: CloudWatch
// Query: dimension_values(us-east-1, Pipeline/Orders, RecordsProcessed, Source)

// "No data in 25 hours" detection query for a Stat panel
// (used later for alerting too)
fields @timestamp, source
| filter source = "$source"
| stats latest(@timestamp) as last_seen
// Grafana's Stat panel can show "time since" relative to last_seen
